 if(e.type==='interactionBeat')$('joke').textContent=e.activity.phases[e.phase];
 if(e.type==='interactionEnd'){stats.lastResult=e.result;stats.lastAward=e.points;const success=successfulInteraction(e),jokes={clock:'打卡三次，人還在公司！',copier:'報表出貨，本人附贈！',coffee:'地板亮了，員工滑了！',busy:'進度99%，手速100%！',water:'水喝飽，人噴走！',chair:'轉職成功：空運部門！',parcel:'收件人：明天的自己！',microwave:'便當升溫，人升空！',shredder:'薪水救回，預算碎滿地！',server:'系統復活，工程師起飛！',boss:'主管用腳蓋章！',launcher:'公文比本人先到！'};comic((success?jokes[e.activity.id]||e.activity.phases[2]:'差一點，彈回去再來！')+' +'+e.points,success?2:1);if(success)sound('success',e.activity.id);else sound('hit');$('joke').textContent=success?'獎金入袋！':'準備救球';const g=bumperGroups[e.station.id];if(g)g.userData.pulse=success?1.2:.4;}
 if(e.type==='save'){comic((e.precise?'精準救球！ +':'續命成功 +')+e.points);sound('save');burst(game.ball.x,game.ball.z,'chair',true);}
 if(e.type==='over')endGame();
}}
