const baselineBytes=actual(new URL('../../docs/pinball/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'fecf4586195100c5f7ce06c42c27d406871cdbf2f45d1f81ca22b77c3f54c554','immutable Pinball parent and admitted paths');
