export function verifyBase(b){
 assert.equal(b.baseCommit,'8d5a131bfa268c8e72fae6fa2a4735cd30a65d9e');assert.equal(b.baseTree,'0072e34de52c10f59d0c7f53cf96774e4c5ec407');assert.deepEqual(b,baseline);
