import test from 'node:test';import assert from 'node:assert/strict';import{readFileSync}from'node:fs';import{database}from'./helpers/leaderboard-sqlite.mjs';import{PlayCountsRepository}from'../worker/play-counts/repository.mjs';
const now=1793620800000,base={game:'hurdles',deviceId:'22222222-2222-4222-8222-222222222222',runId:'11111111-1111-4111-8111-111111111111',startedAt:now};async function setup(){const db=await database();db.raw.run(readFileSync(new URL('../worker/play-counts/002.sql',import.meta.url),'utf8'));return{db,r:new PlayCountsRepository(db,'qa')}}
test('new empty counters and atomic concurrent same receipt only count once',async()=>{const{db,r}=await setup();assert.deepEqual(await r.totals(),Object.fromEntries(['long-jump','hurdles','high-jump','pole-vault','shot-put','discus','reaction-rod','beer-slide','tower-climb','fast-hands','fast-hands-catch','fast-hands-duel','courtesy-contest','taiwanfighter','home'].map(k=>[k,{count:0,since:null}])));const results=await Promise.all([r.start(base,now),r.start(base,now)]);assert.equal(results.filter(x=>x.duplicate).length,1);assert.equal((await r.totals()).hurdles.count,1);assert.equal((await r.totals()).hurdles.since,now);assert.equal((await r.start({...base,game:'long-jump'},now)).error,'conflict');assert.equal(db.raw.exec('SELECT count(*) FROM leaderboard_best')[0].values[0][0],0);});
